-- Clean bootstrap 015: profile hardening, totals, stock synchronization and support.
CREATE OR REPLACE FUNCTION public.prevent_profile_privilege_escalation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF current_setting('app.role_change_rpc',true) IS DISTINCT FROM 'on' AND (NEW.role_id IS DISTINCT FROM OLD.role_id OR NEW.role IS DISTINCT FROM OLD.role OR NEW.sector IS DISTINCT FROM OLD.sector OR NEW.is_active IS DISTINCT FROM OLD.is_active OR NEW.must_change_password IS DISTINCT FROM OLD.must_change_password) THEN RAISE EXCEPTION 'Privileged profile fields require a secured RPC' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS prevent_profile_privilege_escalation_trigger ON public.user_profiles; CREATE TRIGGER prevent_profile_privilege_escalation_trigger BEFORE UPDATE ON public.user_profiles FOR EACH ROW EXECUTE FUNCTION public.prevent_profile_privilege_escalation();
CREATE OR REPLACE FUNCTION public.recalculate_sales_order_totals() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oid uuid:=COALESCE(NEW.order_id,OLD.order_id); subtotal_value numeric; BEGIN SELECT COALESCE(sum(line_total),0) INTO subtotal_value FROM public.order_items WHERE order_id=oid; UPDATE public.sales_orders SET subtotal=subtotal_value,total_amount=greatest(0,subtotal_value+tax_amount-discount_amount),updated_at=now() WHERE id=oid; RETURN COALESCE(NEW,OLD); END $$;
DROP TRIGGER IF EXISTS recalculate_sales_order_totals_trigger ON public.order_items; CREATE TRIGGER recalculate_sales_order_totals_trigger AFTER INSERT OR UPDATE OR DELETE ON public.order_items FOR EACH ROW EXECUTE FUNCTION public.recalculate_sales_order_totals();
CREATE OR REPLACE FUNCTION public.sync_inventory_stock_from_movements() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pid uuid:=COALESCE(NEW.product_id,OLD.product_id); wid uuid:=COALESCE(NEW.warehouse_id,OLD.warehouse_id); qty integer; BEGIN SELECT COALESCE(sum(CASE movement_type WHEN 'in' THEN quantity WHEN 'return' THEN quantity WHEN 'out' THEN -quantity ELSE quantity END),0)::integer INTO qty FROM public.stock_movements WHERE product_id=pid AND warehouse_id=wid; IF qty<0 THEN RAISE EXCEPTION 'Stock cannot be negative'; END IF; INSERT INTO public.inventory_stock(product_id,warehouse_id,quantity) VALUES(pid,wid,qty) ON CONFLICT(product_id,warehouse_id) DO UPDATE SET quantity=EXCLUDED.quantity,updated_at=now(); RETURN COALESCE(NEW,OLD); END $$;
DROP TRIGGER IF EXISTS sync_inventory_stock_trigger ON public.stock_movements; CREATE TRIGGER sync_inventory_stock_trigger AFTER INSERT OR UPDATE OR DELETE ON public.stock_movements FOR EACH ROW EXECUTE FUNCTION public.sync_inventory_stock_from_movements();
CREATE TABLE IF NOT EXISTS public.support_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid REFERENCES public.customers(id) ON DELETE SET NULL,user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,subject text NOT NULL,description text NOT NULL,status text NOT NULL DEFAULT 'open',priority text NOT NULL DEFAULT 'normal',assigned_to uuid REFERENCES auth.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); ALTER TABLE public.support_tickets ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tickets_access ON public.support_tickets;
CREATE POLICY tickets_access ON public.support_tickets FOR SELECT TO authenticated USING(public.is_admin() OR user_id=auth.uid() OR assigned_to=auth.uid());
